head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/



	//----W-Craft WebSquare 변환 확인: include----//
include("../js/utils.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/libRoundPanel.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/common.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/stf.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/session.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/controlResize.js"); // 화면 리사이징

scwin.vScrenID = "ULDFIS00200_11.gfm";
scwin.vKisCd = ""; // 조회조건 기업코드
scwin.vAcntclsDt = "";
scwin.onpageload = function() {
};
scwin.onpageunload = function() {
}; // 조회조건 결산일자

/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
    // 결산일자 조회

	//----W-Craft WebSquare 변환 확인: fn_SrchAcntclsDt----//
    $c.frame.path("../frame_head").fn_SrchAcntclsDt();
};


/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function() {
    dts_EqmtConstrSchd.removeAll();
};


/**
 *  조회조건 유효성 체크
 */
scwin.fn_ChkValid = function() {
    //필수항목 체크.

	//----W-Craft WebSquare 변환 확인: fn_GetKisCd----//
    scwin.vKisCd = $c.frame.path("../frame_head").fn_GetKisCd();

	//----W-Craft WebSquare 변환 확인: fn_GetAcntclsDt----//
    scwin.vAcntclsDt = $c.frame.path("../frame_head").fn_GetAcntclsDt();
    if (scwin.vKisCd == "" || scwin.vAcntclsDt == "") {
        return false;
    }
    return true;
};


/**
 * 설비증설계획 조회
 */
scwin.fn_Search = function() {
    //데이터셋 초기화
    scwin.fn_InitDs();

    // 조회조건 체크.
    if (!scwin.fn_ChkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_EqmtConstrSchd);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.fis.select.eqmtConstrSchd" + "&outputMessageId=FIS_EQMT_CONSTR_SCHD" + "&param01=" + scwin.vKisCd + "&param02=" + scwin.vAcntclsDt;
    dts_EqmtConstrSchd.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_EqmtConstrSchd.Reset();
};


/**
 * 그리드 타이틀 세팅.
 */
scwin.fn_SetGrdTitle = function() {
    $c.cm.setColumnProp(grd_EqmtConstrSchd, "PAYSCHD_AMT1", "Name", dts_EqmtConstrSchd.getCellData(0, "PAYSCHD_YY1") + "연도");
    $c.cm.setColumnProp(grd_EqmtConstrSchd, "PAYSCHD_AMT2", "Name", dts_EqmtConstrSchd.getCellData(0, "PAYSCHD_YY2") + "연도");
    $c.cm.setColumnProp(grd_EqmtConstrSchd, "PAYSCHD_AMT3", "Name", dts_EqmtConstrSchd.getCellData(0, "PAYSCHD_YY3") + "연도");
    $c.cm.setColumnProp(grd_EqmtConstrSchd, "PAYSCHD_AMT4", "Name", dts_EqmtConstrSchd.getCellData(0, "PAYSCHD_YY4") + "연도");
};


/**
 *  엑셀파일다운로드
 */
scwin.fn_excel_download = function() {
    if (dts_EqmtConstrSchd.getTotalRow() <= 0) {
        alert("조회된 데이터가 없습니다.");
        return;
    }
    $c.data.downloadGridViewExcel(grd_EqmtConstrSchd, "설비증설계획", "", "8");
};
scwin.gform_onload = function() {
    scwin.fn_Init();
};
scwin.dts_EqmtConstrSchd_OnLoadError = function() {
    $c.cm.CloseWin(-1, grd_EqmtConstrSchd);
    $c.stf.alert_error(dts_EqmtConstrSchd);
};
scwin.dts_EqmtConstrSchd_OnLoadCompleted = function(rowcount) {
    if (dts_EqmtConstrSchd.errorMsg) {
        alert(dts_EqmtConstrSchd.errorMsg);
    }

    // 그리드 타이틀 세팅.
    scwin.fn_SetGrdTitle();
    $c.cm.CloseWin(rowcount, grd_EqmtConstrSchd);
};
